mapper.select:
SELECT t.* FROM ( SELECT DISTINCT s.* FROM school s LEFT JOIN school_detail d ON d.school_id = s.id
AND s.province = #{province}
AND s.level = #{level}
AND d.major_name LIKE CONCAT('%', #{majorName}, '%')
AND s.name LIKE CONCAT('%', #{keyword}, '%')
) t ORDER BY CASE t.level WHEN '985' THEN 0 WHEN '211' THEN 1 WHEN '双一流' THEN 2 WHEN '普通本科' THEN 3 ELSE 4 END, t.id
